LORI_PHRASES = {
    "می های کجا رووی": "",
    "چه مه کی": "",
    "فرره خستم": "",
    "بیا و ای چه بشین": "",
    "غذا هردیه": "",
    "فردا میریه مدرسه": "",
    "ای فرره خووه": "",
    "عجله نک": "",
    "چی بییه": "",
    "کا بیت": "",
}


def normalize(text):
    text = text.strip()
    for old, new in {
        "ي": "ی",
        "ى": "ی",
        "ك": "ک",
        "\u200c": " ",
    }.items():
        text = text.replace(old, new)
    return " ".join(text.split())


def remove_diacritics(text):
    # فقط برای جست‌وجو؛ شکل ذخیره‌شدهٔ واژه‌ها تغییر نمی‌کند.
    marks = "ًٌٍَُِّْٰٕٓٔ"
    return "".join(ch for ch in text if ch not in marks)


def normalize_lori_for_lookup(text):
    """
    شکل جست‌وجو:
    - یکسان‌سازی حروف عربی/فارسی
    - نادیده‌گرفتن حرکات و نشانه‌گذاری
    - نادیده‌گرفتن فاصله‌ها؛ حتی اگر فاصله‌ای جا افتاده یا اضافه باشد
    """
    text = normalize(remove_diacritics(text))
    text = re.sub(r"[،,؛;:.!?؟]+", "", text)
    return "".join(text.split())


def persian_to_lori(text):
    """فارسی → لری؛ ترتیب معادل‌ها دقیقاً حفظ می‌شود."""
    text = normalize(text)

    # ابتدا تطبیق دقیق
    for persian, lori_words in PERSIAN_TO_LORI.items():
        if normalize(persian) == text:
            return "، ".join(lori_words)

    # اگر فاصله‌ای اضافه شده یا جا افتاده باشد
    key = normalize_lori_for_lookup(text)
    for persian, lori_words in PERSIAN_TO_LORI.items():
        if normalize_lori_for_lookup(persian) == key:
            return "، ".join(lori_words)

    return None


def build_lori_index():
    """ایجاد نمایهٔ لری → فارسی."""
    index = {}

    for persian, lori_words in PERSIAN_TO_LORI.items():
        for lori in lori_words:
            key = normalize_lori_for_lookup(lori)

            if key not in index:
                index[key] = []

            if persian not in index[key]:
                index[key].append(persian)

    return index


LORI_INDEX = build_lori_index()


def lori_to_persian(text):
    """لری → فارسی؛ اگر یک واژه چند معنی داشته باشد، هر معنی را همراه معادل لری نشان می‌دهد."""
    exact = normalize(text)

    # تطبیق دقیق: هر معنی با صورت‌های لری خودش نگه داشته می‌شود.
    exact_matches = []
    for persian, lori_words in PERSIAN_TO_LORI.items():
        if any(normalize(lori) == exact for lori in lori_words):
            if not any(existing_persian == persian for existing_persian, _ in exact_matches):
                exact_matches.append((persian, lori_words))

    if exact_matches:
        # صورت لریِ ذخیره‌شده را دقیقاً با اعراب اصلی در خروجی نگه می‌داریم.
        return "، ".join(
            f"{persian} ({'، '.join(lori_words)})"
            for persian, lori_words in exact_matches
        )

    # جست‌وجوی انعطاف‌پذیر؛ حرکات و فاصله‌های اضافه/جاافتاده نادیده گرفته می‌شوند.
    key = normalize_lori_for_lookup(text)
    normalized_matches = []
    for persian, lori_words in PERSIAN_TO_LORI.items():
        if any(normalize_lori_for_lookup(lori) == key for lori in lori_words):
            if not any(existing_persian == persian for existing_persian, _ in normalized_matches):
                normalized_matches.append((persian, lori_words))

    if normalized_matches:
        # حتی اگر کاربر اعراب را ننوشته باشد، صورت معیار و اعراب‌دار از فرهنگ نمایش داده می‌شود.
        return "، ".join(
            f"{persian} ({'، '.join(lori_words)})"
            for persian, lori_words in normalized_matches
        )

    for phrase in LORI_PHRASES:
        if normalize(phrase) == exact:
            return (
                LORI_PHRASES[phrase]
                if LORI_PHRASES[phrase]
                else "این عبارت ثبت شده، اما معنی فارسی آن هنوز وارد نشده است."
            )

    for phrase in LORI_PHRASES:
        if normalize_lori_for_lookup(phrase) == key:
            return (
                LORI_PHRASES[phrase]
                if LORI_PHRASES[phrase]
                else "این عبارت ثبت شده، اما معنی فارسی آن هنوز وارد نشده است."
            )

    return None


direction = "fa_to_lori"


def rtl(widget):
    widget.tag_configure("rtl", justify="right")
    widget.tag_add("rtl", "1.0", "end")


def set_result(text):
    result_box.config(state="normal")
    result_box.delete("1.0", "end")
    result_box.insert("1.0", text)
    rtl(result_box)
    result_box.config(state="disabled")


def translate(event=None):
    text = normalize(input_box.get("1.0", "end-1c"))
    if not text:
        set_result("لطفاً یک کلمه یا عبارت وارد کنید.")
        status_label.config(text="")
        update_category_display("", "")
        return

    result = (
        persian_to_lori(text)
        if direction == "fa_to_lori"
        else lori_to_persian(text)
    )

    if result:
        shown_result = result
        set_result(shown_result)
        status_label.config(text="ترجمه پیدا شد ✅")
    else:
        shown_result = "این واژه یا عبارت در فرهنگ ثبت نشده است."
        set_result(shown_result)
        status_label.config(text="ترجمه پیدا نشد.")

    update_category_display(text, shown_result if result else "")

    # هر جست‌وجوی غیرخالی در سابقه ثبت می‌شود؛ حتی اگر واژه در فرهنگ نباشد.
    add_to_history(text, shown_result, direction)


def load_history():
    """خواندن سابقهٔ ترجمه از فایل محلی؛ در صورت نبودن فایل، فهرست خالی است."""
    try:
        with HISTORY_PATH.open("r", encoding="utf-8") as file:
            data = json.load(file)
        return data if isinstance(data, list) else []
    except (OSError, json.JSONDecodeError):
        return []


def save_history(items):
    """ذخیرهٔ امن سابقه با حفظ حروف فارسی."""
    try:
        with HISTORY_PATH.open("w", encoding="utf-8") as file:
            json.dump(items[-MAX_HISTORY_ITEMS:], file, ensure_ascii=False, indent=2)
        return True
    except OSError:
        return False


def add_to_history(source_text, translated_text, translation_direction):
    items = load_history()
    items.append({
        "input": source_text,
        "result": translated_text,
        "direction": translation_direction,
        "time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    })
    if not save_history(items):
        status_label.config(text="ترجمه انجام شد، اما ذخیرهٔ سابقه ممکن نشد.")


def open_history():
    """نمایش سابقه؛ دابل‌کلیک روی یک مورد آن را به صفحهٔ اصلی برمی‌گرداند."""
    items = list(reversed(load_history()))
    window = tk.Toplevel(root)
    window.title("سابقهٔ ترجمه | لُرواژه")
    window.geometry("780x520")
    window.minsize(600, 380)
    window.configure(bg="#f2f4f7")
    window.transient(root)

    tk.Label(
        window,
        text="🕘 سابقهٔ ترجمه",
        font=("Tahoma", 20, "bold"),
        bg="#f2f4f7",
        fg="#222222",
    ).pack(pady=(16, 8))

    tk.Label(
        window,
        text="برای برگرداندن یک مورد به مترجم، روی آن دوبار کلیک کنید.",
        font=("Tahoma", 10),
        bg="#f2f4f7",
        fg="#666666",
    ).pack(pady=(0, 10))

    list_frame = tk.Frame(window, bg="#f2f4f7")
    list_frame.pack(fill="both", expand=True, padx=18, pady=4)

    scrollbar = tk.Scrollbar(list_frame)
    scrollbar.pack(side="left", fill="y")

    history_list = tk.Listbox(
        list_frame,
        font=("Tahoma", 11),
        height=16,
        activestyle="dotbox",
        selectmode="browse",
        yscrollcommand=scrollbar.set,
        justify="right",
        bg="white",
        fg="#222222",
        selectbackground="#3478f6",
        selectforeground="white",
        relief="solid",
        borderwidth=1,
    )
    history_list.pack(side="right", fill="both", expand=True)
    scrollbar.config(command=history_list.yview)

    if not items:
        history_list.insert("end", "هنوز ترجمه‌ای ثبت نشده است.")
        history_list.config(state="disabled")
    else:
        for item in items:
            # علامت‌های LRM دور فلش، جهت پیکان را در متن فارسی/راست‌به‌چپ ثابت نگه می‌دارند.
            arrow = "\u200e→\u200e"
            direction_label = (
                f"فارسی {arrow} لری"
                if item.get("direction") == "fa_to_lori"
                else f"لری {arrow} فارسی"
            )
            source_text = str(item.get("input", ""))
            result_text = str(item.get("result", ""))
            line = (
                f"{item.get('time', '')}   |   {direction_label}   |   "
                f"{source_text}   {arrow}   {result_text}"
            )
            history_list.insert("end", line)

    def restore_selected(event=None):
        selection = history_list.curselection()
        if not selection or not items:
            return
        item = items[selection[0]]
        input_box.delete("1.0", "end")
        input_box.insert("1.0", item.get("input", ""))
        rtl(input_box)
        set_result(item.get("result", ""))
        update_category_display(item.get("input", ""), item.get("result", ""))
        if item.get("direction") == "fa_to_lori":
            set_direction_without_clearing("fa_to_lori")
        else:
            set_direction_without_clearing("lori_to_fa")
        status_label.config(text="مورد انتخاب‌شده از سابقه بارگذاری شد.")
        window.destroy()

    def clear_history():
        if not items:
            return
        if not messagebox.askyesno("پاک‌کردن سابقه", "همهٔ موارد سابقهٔ ترجمه پاک شوند؟", parent=window):
            return
        if save_history([]):
            history_list.config(state="normal")
            history_list.delete(0, "end")
            history_list.insert("end", "هنوز ترجمه‌ای ثبت نشده است.")
            history_list.config(state="disabled")
            items.clear()
            status_label.config(text="سابقهٔ ترجمه پاک شد.")

    history_list.bind("<Double-Button-1>", restore_selected)

    button_frame = tk.Frame(window, bg="#f2f4f7")
    button_frame.pack(pady=12)

    tk.Button(
        button_frame,
        text="بارگذاری مورد انتخاب‌شده",
        font=("Tahoma", 10, "bold"),
        command=restore_selected,
        cursor="hand2",
    ).pack(side="right", padx=5)

    tk.Button(
        button_frame,
        text="پاک‌کردن سابقه",
        font=("Tahoma", 10),
        command=clear_history,
        cursor="hand2",
    ).pack(side="right", padx=5)

    tk.Button(
        button_frame,
        text="بستن",
        font=("Tahoma", 10),
        command=window.destroy,
        cursor="hand2",
    ).pack(side="right", padx=5)


def set_direction_without_clearing(new_direction):
    """تغییر جهت هنگام بارگذاری سابقه، بدون پاک‌شدن ورودی و نتیجه."""
    global direction
    direction = new_direction
    if direction == "fa_to_lori":
        direction_button.config(text="فارسی \u200e→\u200e لری")
        input_label.config(text="واژه یا عبارت فارسی:")
    else:
        direction_button.config(text="لری \u200e→\u200e فارسی")
        input_label.config(text="واژه یا عبارت لری:")


def swap_direction():
    global direction

    if direction == "fa_to_lori":
        direction = "lori_to_fa"
        direction_button.config(text="لری \u200e→\u200e فارسی")
        input_label.config(text="واژه یا عبارت لری:")
    else:
        direction = "fa_to_lori"
        direction_button.config(text="فارسی \u200e→\u200e لری")
        input_label.config(text="واژه یا عبارت فارسی:")

    clear_all()
    status_label.config(text="جهت ترجمه تغییر کرد.")


def clear_all():
    input_box.delete("1.0", "end")
    set_result("")
    status_label.config(text="")
    update_category_display("", "")
    hide_word_suggestions()
    input_box.focus_set()
