def copy_output_text():
    """کپی متن خروجی به کلیپ‌بورد سیستم."""
    text = result_box.get("1.0", "end-1c")
    if not text.strip():
        status_label.config(text="کادر خروجی خالی است.")
        return
    try:
        root.clipboard_clear()
        root.clipboard_append(text)
        root.update_idletasks()
        status_label.config(text="متن خروجی کپی شد ✅")
    except tk.TclError:
        status_label.config(text="کپی متن خروجی انجام نشد؛ دوباره امتحان کن.")


