def _category_key(value):
    """کلید دسته‌بندی با حذف حرکات و علائم؛ فاصلهٔ بین واژه‌ها حفظ می‌شود."""
    value = normalize(remove_diacritics(str(value))).lower()
    value = re.sub(r"[،,؛;:.!?؟()\[\]{}<>/\\|]+", " ", value)
    return normalize(value)


def _category_aliases(category):
    aliases = list(CATEGORY_MEMBERS.get(category, []))
    wanted = {_category_key(word) for word in CATEGORY_MEMBERS.get(category, [])}
    for persian, lori_words in PERSIAN_TO_LORI.items():
        if _category_key(persian) in wanted:
            aliases.extend(lori_words)
    # با حذف تکراری‌ها، ترتیب فهرست حفظ می‌شود.
    return list(dict.fromkeys(_category_key(word) for word in aliases if word))


CATEGORY_ALIASES = {category: _category_aliases(category) for category in CATEGORY_MEMBERS}


def detect_category(source_text, translated_text=""):
    """تشخیص دسته از واژهٔ ورودی یا معادل ترجمه‌شده، بدون نیاز به اینترنت."""
    combined = _category_key(f"{source_text} {translated_text}")
    padded = f" {combined} "
    # بررسی مرز کلمه مانع از آن می‌شود که مثلاً «در» داخل «درد» تشخیص داده شود.
    for category, aliases in CATEGORY_ALIASES.items():
        for alias in aliases:
            if alias and f" {alias} " in padded:
                return category
    return "واژهٔ عمومی"



