def update_category_display(source_text="", translated_text=""):
    """Only reveal the high-quality category image while the input has text."""
    text_for_display = normalize(str(source_text)).strip()
    if not text_for_display:
        if category_panel.winfo_manager():
            category_panel.pack_forget()
        return

    category = detect_category(source_text, translated_text)
    category_visual_state["category"] = category
    style = CATEGORY_STYLE.get(category, CATEGORY_STYLE["واژهٔ عمومی"])
    category_title.config(text=f"دسته: {category}", fg=style["color"])
    icon_key = style["icon"]
    category_image_label.config(image=CATEGORY_PHOTOS.get(icon_key, CATEGORY_PHOTOS["general"]))
    if not category_panel.winfo_manager():
        category_panel.pack(side="right", fill="y")


# واژهٔ نمونه برای پیشنهاد فارسی؛ تا زمان ثبت معادل لری، فقط پیشنهاد داده می‌شود.
PERSIAN_SUGGESTION_EXTRA = ["چاق"]
MAX_WORD_SUGGESTIONS = 6


def get_source_words():
    """واژه‌های زبان مبدأ در جهت فعلی؛ خروجی ترجمه در پیشنهادها مخلوط نمی‌شود."""
    if direction == "fa_to_lori":
        words = list(PERSIAN_SUGGESTION_EXTRA)
        words.extend(PERSIAN_TO_LORI.keys())
        return list(dict.fromkeys(word for word in words if word))

    # در حالت لری → فارسی، فقط صورت‌های لری از فرهنگ و عبارت‌های لری نمایش داده می‌شوند.
    words = []
    for lori_forms in PERSIAN_TO_LORI.values():
        words.extend(lori_forms)
    words.extend(LORI_PHRASES.keys())
    return list(dict.fromkeys(word for word in words if word))


def get_word_suggestions(query):
    """حدسِ پیشوندی با نادیده گرفتن حرکت‌ها و فاصله‌ها فقط هنگام جست‌وجو."""
    query_key = normalize_lori_for_lookup(query)
    if len(query_key) < 2:
        return []

    words = get_source_words()
    matches = []
    seen_display = set()
    for word in words:
        word_key = normalize_lori_for_lookup(word)
        if not word_key or word_key == query_key:
            continue
        if word_key.startswith(query_key) and word not in seen_display:
            matches.append(word)
            seen_display.add(word)

    # مثال کاربر: برای «چا»، «چاق» و «چاقو» کنار هم بیایند.
    # سایر پیشنهادها، بدون تغییر ترتیب واژه‌های فرهنگ، بعد از این گروه قرار می‌گیرند.
    preferred_roots = [
        normalize_lori_for_lookup(word)
        for word in PERSIAN_SUGGESTION_EXTRA
        if normalize_lori_for_lookup(word).startswith(query_key)
    ] if direction == "fa_to_lori" else []

    if preferred_roots:
        original_order = {word: i for i, word in enumerate(matches)}

        def suggestion_rank(word):
            key = normalize_lori_for_lookup(word)
            for root_key in preferred_roots:
                if key == root_key:
                    return (0, preferred_roots.index(root_key), original_order[word])
                if key.startswith(root_key):
                    return (1, preferred_roots.index(root_key), original_order[word])
            return (2, 0, original_order[word])

        matches.sort(key=suggestion_rank)

    return matches[:MAX_WORD_SUGGESTIONS]


def hide_word_suggestions():
    if suggestion_panel.winfo_manager():
        suggestion_panel.pack_forget()


def select_word_suggestion(word):
    """با انتخاب پیشنهاد، همان املای اصلی را در ورودی قرار بده؛ ترجمه با دکمه انجام می‌شود."""
    input_box.delete("1.0", "end")
    input_box.insert("1.0", word)
    rtl(input_box)
    hide_word_suggestions()
    input_box.focus_set()
    input_box.mark_set("insert", "end-1c")
    update_category_display(word, "")


def update_word_suggestions(query):
    suggestions = get_word_suggestions(query)
    for child in suggestion_items_frame.winfo_children():
        child.destroy()

    if not suggestions:
        hide_word_suggestions()
        return

    for word in suggestions:
        tk.Button(
            suggestion_items_frame,
            text=word,
            font=("Tahoma", 11, "bold"),
            cursor="hand2",
            relief="raised",
            bd=1,
            padx=8,
            pady=3,
            bg="#ffffff",
            fg="#174ea6",
            activebackground="#dce8ff",
            activeforeground="#103b80",
            command=lambda selected=word: select_word_suggestion(selected),
        ).pack(side="right", padx=3, pady=2)

    if not suggestion_panel.winfo_manager():
        suggestion_panel.pack(
            before=utility_frame,
            fill="x",
            padx=40,
            pady=(4, 2),
        )


def on_input_change(event=None):
    """Update the category preview and word guesses while typing."""
    rtl(input_box)
    current_text = input_box.get("1.0", "end-1c")
    update_category_display(current_text, "")
    update_word_suggestions(current_text)


